parameters.jsCode:
// Extract data from TradingView alert
const tvData = $input.first().json;

// Parse TradingView message
const symbol = tvData.symbol || tvData.ticker || 'UNKNOWN';
const price = parseFloat(tvData.close || tvData.price || 0);
const volume = parseInt(tvData.volume || 0);
const timeframe = tvData.timeframe || tvData.interval || '1D';

// Get chart screenshot URL (if provided)
const chartUrl = tvData.screenshot_url || tvData.chart_url || '';

return {
  json: {
    symbol: symbol,
    price: price,
    volume: volume,
    timeframe: timeframe,
    chartUrl: chartUrl,
    rawData: tvData,
    timestamp: new Date().toISOString()
  }
};

// Parse Claude AI response
const response = $input.first().json;
const aiText = response.candidates[0]?.content?.parts[0]?.text || '{}';

// Extract JSON from response
let analysis = {};
try {
  // Try to parse as JSON
  const jsonMatch = aiText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch (error) {
  // Fallback parsing
  analysis = {
    verdict: 'SIDEWAYS',
    score: 50,
    fundamental_score: 50,
    technical_score: 50,
    momentum_score: 50,
    sentiment_score: 50,
    risk_score: 50,
    insight: aiText.substring(0, 200),
    recommendation: 'HOLD - Tunggu konfirmasi lebih lanjut'
  };
}

// Get stock name (you can add API call to get company name)
const stockNames = {
  'BBCA': 'PT Bank Central Asia Tbk.',
  'BBRI': 'PT Bank Rakyat Indonesia Tbk.',
  'BMRI': 'PT Bank Mandiri Tbk.',
  'TLKM': 'PT Telkom Indonesia Tbk.',
  'ASII': 'PT Astra International Tbk.',
  'GOTO': 'PT GoTo Gojek Tokopedia Tbk.',
  'BREN': 'PT Barito Renewables Energy Tbk.',
  'ADRO': 'PT Adaro Energy Indonesia Tbk.'
};

const symbol = $node["Parse TradingView Data"].json.symbol;
const price = $node["Parse TradingView Data"].json.price;

return {
  json: {
    symbol: symbol,
    name: stockNames[symbol] || `PT ${symbol} Tbk.`,
    price: price,
    score: analysis.score || 50,
    verdict: analysis.verdict || 'SIDEWAYS',
    status: analysis.verdict || 'Sideways',
    fundamental_score: analysis.fundamental_score || 50,
    technical_score: analysis.technical_score || 50,
    momentum_score: analysis.momentum_score || 50,
    sentiment_score: analysis.sentiment_score || 50,
    risk_score: analysis.risk_score || 50,
    insight: analysis.insight || 'Analisis sedang diproses',
    recommendation: analysis.recommendation || 'HOLD',
    analyzed_at: new Date().toISOString(),
    source: 'tradingview',
    raw_ai_response: aiText
  }
};

